examples.setup:
CREATE TABLE accounts (id text PRIMARY KEY, balance int NOT NULL);
CREATE TABLE payments (
  id         int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  account_id text NOT NULL REFERENCES accounts,
  amount     int NOT NULL
);
INSERT INTO accounts VALUES ('a', 100);

pitfalls.good:
UPDATE accounts SET balance = balance - 50
WHERE id = 'a' AND balance >= 50
RETURNING balance;

files.examples/01_lost_update.sql:
-- Read, compute in the application, write the result back: two withdrawals
-- (A takes 30, B takes 50) from account a, which holds 100.
A: BEGIN;
B: BEGIN;
A: SELECT balance FROM accounts WHERE id = 'a';
B: SELECT balance FROM accounts WHERE id = 'a';
A: UPDATE accounts SET balance = 70 WHERE id = 'a';
A: COMMIT;
B: UPDATE accounts SET balance = 50 WHERE id = 'a';
B: COMMIT;

-- The same two withdrawals from account b, reading with FOR UPDATE.
A: BEGIN;
B: BEGIN;
A: SELECT balance FROM accounts WHERE id = 'b' FOR UPDATE;
B: SELECT balance FROM accounts WHERE id = 'b' FOR UPDATE;
A: UPDATE accounts SET balance = 70 WHERE id = 'b';
A: COMMIT;
-- B's read returned 70 once A committed, so B computes 70 - 50.
B: UPDATE accounts SET balance = 20 WHERE id = 'b';
B: COMMIT;

-- Account a lost A's withdrawal; account b has both.
A: SELECT id, balance FROM accounts ORDER BY id;

files.examples/02_key_share.sql:
-- payments.account_id REFERENCES accounts. Inserting a payment makes
-- Postgres take FOR KEY SHARE on the account row: "don't delete it, don't
-- change its key until I commit".

-- A plain UPDATE of a non-key column takes FOR NO KEY UPDATE.
A: BEGIN;
A: UPDATE accounts SET balance = balance - 10 WHERE id = 'a';
B: INSERT INTO payments (account_id, amount) VALUES ('a', 10);
A: COMMIT;

-- SELECT ... FOR UPDATE is stronger than the update needs.
A: BEGIN;
A: SELECT balance FROM accounts WHERE id = 'a' FOR UPDATE;
B: INSERT INTO payments (account_id, amount) VALUES ('a', 20);
A: UPDATE accounts SET balance = balance - 20 WHERE id = 'a';
A: COMMIT;

-- FOR NO KEY UPDATE locks exactly what the UPDATE will lock anyway.
A: BEGIN;
A: SELECT balance FROM accounts WHERE id = 'a' FOR NO KEY UPDATE;
B: INSERT INTO payments (account_id, amount) VALUES ('a', 30);
A: UPDATE accounts SET balance = balance - 30 WHERE id = 'a';
A: COMMIT;

files.examples/03_nowait.sql:
-- A holds the row lock. B tries three ways to get at the row.
A: BEGIN;
A: SELECT balance FROM accounts WHERE id = 'a' FOR UPDATE;

-- NOWAIT: fail at once instead of queueing behind A.
B: SELECT balance FROM accounts WHERE id = 'a' FOR UPDATE NOWAIT;

-- lock_timeout: wait, but only this long. It covers every lock the
-- statement needs, including the row lock a plain UPDATE takes.
B: SET lock_timeout = '100ms';
B: UPDATE accounts SET balance = 0 WHERE id = 'a';

-- A plain read never waits for a row lock.
B: SELECT balance FROM accounts WHERE id = 'a';
A: COMMIT;
